import Foundation
import PixlBackup
import Testing
@testable import PixlLibrary

/// The stage 2b, milestone 2 golden vectors (`fastrp`, `ppr`, `islands`, `arms`, `listmixes`, `islandfeatures`,
/// `islandmixes`, `homeplan`): FastRP embeddings, personalised PageRank, taste islands, the arms' rules, the simple
/// mixes, calibration, the embedding-aware similarity, the island-aware mix planner and the Home page rules.
/// Generated by the Android repo's `./gradlew :brain:generateGolden`, copied here unchanged. The README beside the
/// files says how each `fn` is replayed.
@Suite("Brain stage 2b milestone 2 golden vectors (brainMatchesAndroid)")
struct BrainStage2bM2GoldenTests {
    typealias G = BrainGoldenTests
    typealias S = BrainStage2bGoldenTests
    typealias Value = BrainJson.Value

    // MARK: Small readers and writers

    static func bytes(_ hex: String) -> [UInt8] {
        let u = Array(hex.utf8)
        func nib(_ c: UInt8) -> UInt8 { c >= 97 ? c - 87 : c - 48 }
        var out: [UInt8] = []
        out.reserveCapacity(u.count / 2)
        var i = 0
        while i + 1 < u.count {
            out.append(nib(u[i]) << 4 | nib(u[i + 1]))
            i += 2
        }
        return out
    }

    static func optBytes(_ v: Value, _ k: String) -> [UInt8]? {
        let h = G.string(v, k)
        return h.isEmpty ? nil : bytes(h)
    }

    static func doubles(_ v: Value, _ k: String) -> [Double] { G.array(v, k).map { $0.doubleValue ?? .nan } }
    static func intsOf(_ v: Value, _ k: String) -> [Int] { G.array(v, k).map { Int($0.bareLong ?? 0) } }
    static func i32(_ values: [Int]) -> [Int32] { values.map { Int32(truncatingIfNeeded: $0) } }

    static func hashDoubles(_ v: [Double]) -> Int64 {
        var b = [UInt8](repeating: 0, count: v.count * 8)
        for i in 0..<v.count {
            let bits = v[i].bitPattern
            for k in 0..<8 { b[i * 8 + k] = UInt8(truncatingIfNeeded: bits >> UInt64(8 * k)) }
        }
        return BrainHash.id(BrainHash.fnv1a64(bytes: b))
    }

    static func edges(_ v: Value) -> [[Value]] { G.array(v, "edges").map { $0.arrayValue ?? [] } }

    static func graph(_ v: Value) -> Graph {
        var b = Graph.Builder()
        for e in edges(v) { b.addEdge(e[0].longValue ?? 0, e[1].longValue ?? 0, weight: e[2].doubleValue ?? 0.0) }
        return b.build()
    }

    static func islandTracks(_ v: Value, _ k: String) -> [Islands.Track] {
        G.array(v, k).map {
            Islands.Track(rid: G.long($0, "rid"), aid: G.long($0, "aid"), weight: G.double($0, "w"),
                          recentWeight: G.double($0, "recent"), emb: optBytes($0, "emb"), tags: S.vector($0["tags"]))
        }
    }

    static func writeFit(_ w: inout BrainJson.Writer, _ fit: Islands.Fit) {
        w.int("maxId", fit.maxId)
        w.beginArray("islands")
        for i in fit.islands {
            w.beginObject(); w.int("id", i.id); w.long("medoid", i.medoidRid); w.int("size", i.size)
            w.double("weight", i.weight); w.double("recent", i.recentWeight)
            w.ints("topTags", i18(i.topTags)); w.ints("liftTags", i18(i.liftTags)); w.longs("topArtists", i.topArtists)
            w.long("centroidHash", hashDoubles(i.centroid))
            w.beginArray("head"); for j in 0..<6 { w.doubleItem(i.centroid[j]) }; w.endArray()
            w.endObject()
        }
        w.endArray()
        w.beginArray("members")
        for k in 0..<fit.memberRids.count {
            w.beginArray(); w.longItem(fit.memberRids[k]); w.intItem(fit.memberIslandIds[k]); w.endArray()
        }
        w.endArray()
    }

    static func i18(_ a: [Int]) -> [Int32] { i32(a) }

    static func writeItems(_ w: inout BrainJson.Writer, _ name: String, _ list: [ListMixes.Item]) {
        w.beginArray(name)
        for i in list {
            w.beginArray(); w.longItem(i.rid); w.longItem(i.aid); w.doubleItem(i.score); w.intItem(Int(i.arm)); w.endArray()
        }
        w.endArray()
    }

    /// The `out` object of a case, parsed again (a few cases take their sample points from it).
    static func out(_ c: G.Case) throws -> Value { try #require(try BrainJson.parse(c.line)["out"]) }

    // MARK: fastrp.jsonl

    @Test func fastRpMatchesAndroid() throws {
        var report = G.Report(file: "fastrp.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("fastrp.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "embed":
                let emb = FastRp.embed(Self.graph(i))
                let want = try Self.out(c)
                let pairs = G.array(want, "cos").map { $0.arrayValue ?? [] }
                report.record(c, c.matches {
                    $0.int("version", emb.version); $0.int("nodes", emb.size)
                    $0.beginArray("vectors")
                    for k in 0..<emb.size {
                        $0.beginArray(); $0.longItem(emb.idAt(k)); $0.stringItem(S.hex(emb.vector(emb.idAt(k)) ?? [])); $0.endArray()
                    }
                    $0.endArray()
                    $0.beginArray("cos")
                    for p in pairs {
                        let a = p[0].longValue ?? 0
                        let b = p[1].longValue ?? 0
                        $0.beginArray(); $0.longItem(a); $0.longItem(b); $0.doubleItem(emb.cos(a, b)); $0.endArray()
                    }
                    $0.endArray()
                })
            case "projection":
                let id = G.long(i, "id")
                report.record(c, c.matches {
                    $0.long("hash", BrainHash.id(FastRp.nodeHash(id)))
                    $0.beginArray("row")
                    for j in 0..<Embeddings.dim { $0.doubleItem(FastRp.projection(FastRp.nodeHash(id), j)) }
                    $0.endArray()
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 30)
        #expect(counts["embed"] == 10)
        #expect(counts["projection"] == 20)
    }

    // MARK: ppr.jsonl

    @Test func pprMatchesAndroid() throws {
        var report = G.Report(file: "ppr.jsonl")
        for c in try G.cases("ppr.jsonl") {
            let i = c.input
            let r = Ppr.run(Self.graph(i), seedIds: G.longs(i, "seeds"), seedWeights: Self.doubles(i, "weights"),
                            top: Int(G.int(i, "top")))
            report.record(c, c.fn == "ppr" && c.matches {
                $0.beginArray("result")
                for k in 0..<r.size { $0.beginArray(); $0.longItem(r.ids[k]); $0.doubleItem(r.scores[k]); $0.endArray() }
                $0.endArray()
            })
        }
        report.verify(atLeast: 12)
    }

    // MARK: islands.jsonl

    @Test func islandsMatchAndroid() throws {
        let atlas = try S.atlas()
        var report = G.Report(file: "islands.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("islands.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "fit":
                let fit = Islands.fit(Self.islandTracks(i, "tracks"))
                report.record(c, c.matches { Self.writeFit(&$0, fit) })
            case "name":
                let lift = Self.intsOf(i, "liftTags")
                let names = IslandNames.pick(atlas, lift)
                report.record(c, c.matches { $0.ints("names", Self.i32(names)) })
            case "match":
                let before = Islands.fit(Self.islandTracks(i, "first"))
                let after = Islands.fit(Self.islandTracks(i, "second"), previous: before.islands, lastId: before.maxId)
                report.record(c, c.matches {
                    $0.int("firstMaxId", before.maxId)
                    Self.writeFit(&$0, after)
                })
            case "point":
                let p = Islands.point(Self.optBytes(i, "emb"), S.vector(i["tags"]))
                report.record(c, c.matches {
                    if let p {
                        $0.long("hash", Self.hashDoubles(p))
                        $0.beginArray("head"); for j in 0..<4 { $0.doubleItem(p[j]) }; $0.endArray()
                    } else {
                        $0.nullValue("point")
                    }
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 71)
        #expect(counts["fit"] == 10)
        #expect(counts["match"] == 6)
        #expect(counts["point"] == 30)
    }

    // MARK: arms.jsonl

    @Test func armsMatchAndroid() throws {
        let atlas = try S.atlas()
        var report = G.Report(file: "arms.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("arms.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "back":
                let back = ArmRules.isBack(completions: Int(G.int(i, "completions")), lastPlayedMs: G.long(i, "lastMs"),
                                           nowMs: G.long(i, "nowMs"), inLibrary: G.bool(i, "inLibrary"))
                report.record(c, c.matches { $0.bool("back", back) })
            case "simSources":
                let out = ArmRules.simSources(aids: G.longs(i, "aids"), aff: Self.doubles(i, "aff"),
                                              weight: Self.doubles(i, "weight"), limit: Int(G.int(i, "limit")))
                report.record(c, c.matches { $0.longs("sources", out) })
            case "adjacent":
                var played: [Int: Double] = [:]
                for p in G.array(i, "shares") {
                    let a = p.arrayValue ?? []
                    played[Int(a[0].bareLong ?? 0)] = a[1].doubleValue ?? 0.0
                }
                let out = ArmRules.adjacentGenres(atlas, loved: Self.intsOf(i, "loved"), share: { played[$0] ?? 0.0 },
                                                  limit: Int(G.int(i, "limit")))
                report.record(c, c.matches { $0.ints("adjacent", Self.i32(out)) })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 77)
        #expect(counts["back"] == 40)
        #expect(counts["simSources"] == 12)
        #expect(counts["adjacent"] == 25)
    }

    // MARK: listmixes.jsonl

    @Test func listMixesMatchAndroid() throws {
        var report = G.Report(file: "listmixes.jsonl")
        for c in try G.cases("listmixes.jsonl") {
            let i = c.input
            let now = G.long(i, "nowMs")
            let rids = G.longs(i, "rids")
            let aids = G.longs(i, "aids")
            let albums = G.longs(i, "albums")
            var state = Affinity.State()
            for s in G.array(i, "steps") {
                let a = s.arrayValue ?? []
                Affinity.apply(&state, family: Family.track, key: a[0].longValue ?? 0, r: Double(a[2].bareLong ?? 0) / 10.0,
                               c: 0.5 + Double(a[3].bareLong ?? 0) / 2.0, part: 1.0, tMs: a[1].longValue ?? 0)
            }
            var served: [Int64: Int32] = [:]
            for p in G.array(i, "served") {
                let a = p.arrayValue ?? []
                served[a[0].longValue ?? 0] = Int32(truncatingIfNeeded: a[1].bareLong ?? 0)
            }
            let excluded = Set(G.longs(i, "excluded"))
            let tie = G.long(i, "tieSeed")
            let onRepeat = ListMixes.fill(ListMixes.onRepeat(state, rids: rids, aids: aids, albumKeys: albums, nowMs: now),
                                          count: ListMixes.size, excluded: excluded, tieSeed: tie)
            let rediscover = ListMixes.fill(
                ListMixes.rediscover(state, rids: rids, aids: aids, albumKeys: albums, servedTimes: served, nowMs: now),
                count: ListMixes.size, excluded: excluded, tieSeed: tie)
            let heard = G.array(i, "artistHeard").map { ($0.bareLong ?? 0) != 0 }
            let dropped = ListMixes.fill(
                ListMixes.justDropped(rids: rids, aids: aids, albumKeys: albums, artistAff: Self.doubles(i, "artistAff"),
                                      artistHeard: heard, recency: Self.doubles(i, "recency")),
                count: ListMixes.size, excluded: excluded, tieSeed: tie, maxPerArtist: 2)
            report.record(c, c.fn == "lists" && c.matches {
                Self.writeItems(&$0, "onRepeat", onRepeat)
                Self.writeItems(&$0, "rediscover", rediscover)
                Self.writeItems(&$0, "justDropped", dropped)
            })
        }
        report.verify(atLeast: 10)
    }

    // MARK: islandfeatures.jsonl

    @Test func islandFeaturesMatchAndroid() throws {
        var report = G.Report(file: "islandfeatures.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("islandfeatures.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "calibration":
                let weights = Self.doubles(i, "weights")
                let cal = Calibration(weights)
                for p in Self.intsOf(i, "picks") { cal.add(p) }
                report.record(c, c.matches {
                    $0.beginArray("gains")
                    for k in 0..<weights.count { $0.doubleItem(cal.gain(k)) }
                    $0.endArray()
                    $0.double("divergence", cal.divergence())
                })
            case "sim":
                let rids = G.longs(i, "rids")
                let embs = Embeddings.of(version: 1, ids: rids, data: Self.bytes(G.string(i, "emb")))
                var tags: [Int64: Tags.Vector] = [:]
                let list = G.array(i, "tagList")
                for k in 0..<rids.count {
                    let v = S.vector(list[k])
                    if !v.isEmpty { tags[rids[k]] = v }
                }
                let index = SimilarityIndex(Self.graph(i), G.bool(i, "withEmbeddings") ? embs : nil, tags)
                let want = try Self.out(c)
                let pairs = G.array(want, "sims").map { $0.arrayValue ?? [] }
                report.record(c, c.matches {
                    $0.beginArray("sims")
                    for p in pairs {
                        let a = p[0].longValue ?? 0
                        let b = p[1].longValue ?? 0
                        $0.beginArray(); $0.longItem(a); $0.longItem(b); $0.doubleItem(index.sim(a, 0, b, 0)); $0.endArray()
                    }
                    $0.endArray()
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 22)
        #expect(counts["calibration"] == 12)
        #expect(counts["sim"] == 10)
    }

    // MARK: islandmixes.jsonl

    @Test func islandMixesMatchAndroid() throws {
        var report = G.Report(file: "islandmixes.jsonl")
        var caseNo = 0
        for c in try G.cases("islandmixes.jsonl") {
            let i = c.input
            let fitTracks = Self.islandTracks(i, "fitTracks")
            let fit = Islands.fit(fitTracks)
            var cands: [Candidate] = []
            for x in G.array(i, "candidates") {
                cands.append(Candidate(
                    rid: G.long(x, "rid"), aid: G.long(x, "aid"), albumKey: G.long(x, "albumKey"),
                    inLibrary: G.bool(x, "inLibrary"), liked: G.bool(x, "liked"), fromArtistRadio: G.bool(x, "fromArtistRadio"),
                    fromSimilarArtist: G.bool(x, "fromSimilarArtist"), tags: S.vector(x["tags"]), emb: Self.optBytes(x, "emb"),
                    popPermille: Int(x["pop"]?.bareLong ?? -1), fresh: G.bool(x, "fresh"), back: G.bool(x, "back"),
                    edge: G.bool(x, "edge"), artistNew: G.bool(x, "artistNew")))
            }
            var tagsByRid: [Int64: Tags.Vector] = [:]
            for t in fitTracks { if let v = t.tags { tagsByRid[t.rid] = v } }
            let request = MixPlanner.Request(
                kind: G.int(i, "kind"), candidates: cands, seeds: [], nowMs: G.long(i, "nowMs"), tzOffsetMin: 0,
                nuMultiplier: 1.0, salt: BrainHash.id(BrainHash.fnv1a64("salt \(caseNo)")),
                islands: IslandContext(fit.islands), islandIdx: Int(i["islandIdx"]?.bareLong ?? -1), tagsByRid: tagsByRid)
            let plan = MixPlanner.plan(request, affinity: Affinity.State())
            report.record(c, c.fn == "islandMix" && c.matches {
                $0.beginArray("picks")
                for p in plan.picks {
                    $0.beginObject(); $0.long("rid", p.rid); $0.int("arm", Int(p.arm)); $0.int("slot", Int(p.slot))
                    $0.int("slotKind", Int(p.slotKind)); $0.long("key", p.key); $0.int("pQ", Int(p.pQ)); $0.bool("novel", p.novel)
                    $0.endObject()
                }
                $0.endArray()
                $0.int("poolSize", plan.poolSize)
            })
            caseNo += 1
        }
        report.verify(atLeast: 12)
    }

    // MARK: homeplan.jsonl

    static func writeShelfItems(_ w: inout BrainJson.Writer, _ items: [HomePlanner.Item]) {
        w.beginArray("items")
        for i in items { w.beginArray(); w.longItem(i.rid); w.longItem(i.aid); w.intItem(i.key); w.endArray() }
        w.endArray()
    }

    @Test func homePlanMatchesAndroid() throws {
        var report = G.Report(file: "homeplan.jsonl")
        var counts: [String: Int] = [:]
        for c in try G.cases("homeplan.jsonl") {
            counts[c.fn, default: 0] += 1
            let i = c.input
            switch c.fn {
            case "plan":
                var shelves: [HomePlanner.ShelfIn] = []
                for s in G.array(i, "shelves") {
                    let items = G.array(s, "items").map { x -> HomePlanner.Item in
                        let a = x.arrayValue ?? []
                        return HomePlanner.Item(rid: a[0].longValue ?? 0, aid: a[1].longValue ?? 0, key: Int(a[2].bareLong ?? 0))
                    }
                    shelves.append(HomePlanner.ShelfIn(type: G.int(s, "type"), id: G.string(s, "id"), items: items))
                }
                let shown = HomePlanner.plan(shelves)
                report.record(c, c.matches {
                    $0.beginArray("shown")
                    for s in shown {
                        $0.beginObject(); $0.int("type", Int(s.type)); $0.string("id", s.id)
                        Self.writeShelfItems(&$0, s.items)
                        $0.endObject()
                    }
                    $0.endArray()
                })
            case "hero":
                let now = G.long(i, "nowMs")
                let tz = G.int(i, "tzOffsetMin")
                let hero = HomePlanner.hero(hasFirstListen: G.bool(i, "firstListen"), hasTopRelease: G.bool(i, "release"),
                                            dailyCount: Int(G.int(i, "daily")), nowMs: now, tzOffsetMin: tz, salt: G.long(i, "salt"))
                report.record(c, c.matches {
                    $0.int("kind", Int(hero.kind)); $0.int("index", hero.index)
                    $0.int("daypart", Int(HomePlanner.daypart(nowMs: now, tzOffsetMin: tz)))
                    $0.int("weekday", Int(HomePlanner.weekday(nowMs: now, tzOffsetMin: tz)))
                    $0.long("planKey", HomePlanner.planKey(nowMs: now, tzOffsetMin: tz))
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 84)
        #expect(counts["plan"] == 24)
        #expect(counts["hero"] == 60)
    }

    // MARK: The manifest

    @Test func theNewFilesAreInTheManifest() throws {
        let manifest = String(decoding: try G.fixtureData("MANIFEST.sha256"), as: UTF8.self)
        for name in ["fastrp", "ppr", "islands", "arms", "listmixes", "islandfeatures", "islandmixes", "homeplan"] {
            let data = [UInt8](try G.fixtureData("\(name).jsonl"))
            let line = manifest.split(separator: "\n").first { $0.hasSuffix(" \(name).jsonl") || $0.hasSuffix("  \(name).jsonl") }
            let hash = try #require(line.map { String($0.prefix(64)) }, "\(name).jsonl is not in MANIFEST.sha256")
            #expect(SHA256.hex(data) == hash, "\(name).jsonl is not the file Android generated")
        }
    }
}
